window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[242]={"id":"242","numero":242,"titre":"Hyperthyroïdie","objectifs":[{"id":"242-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hyperthyroïdie et de la thyrotoxicose","contenu":"<p>Deux notions à distinguer rigoureusement — c'est la base de tout l'item :</p>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-def\">Hyperthyroïdie</span></th>\n            <td>Excès de production d'hormones thyroïdiennes lié à l'<strong>hyperfonctionnement de la glande thyroïde</strong>.</td>\n          </tr>\n          <tr>\n            <th>Thyrotoxicose</th>\n            <td><strong>Conséquences tissulaires de l'excès d'hormones thyroïdiennes</strong> au niveau des tissus cibles, <span class=\"kw-def\">quelle qu'en soit la cause</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La thyrotoxicose peut résulter de <strong>3 mécanismes</strong> (LiSA) :</p>\n      <ul>\n        <li><strong>Relargage</strong> d'hormones thyroïdiennes préformées — ex : <span class=\"kw-etio\">thyroïdite subaiguë de De Quervain</span>.</li>\n        <li><strong>Hyperproduction</strong> d'hormones par la glande — ex : <span class=\"kw-etio\">maladie de Basedow</span>.</li>\n        <li><strong>Apport exogène</strong> d'hormones thyroïdiennes — <span class=\"kw-etio\">thyrotoxicose factice</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Nuance clé.</strong> La <span class=\"kw-def\">thyrotoxicose</span> peut exister <em>sans</em> hyperfonctionnement glandulaire. La <span class=\"kw-imagerie\">scintigraphie</span> tranche : <span class=\"kw-imagerie\">blanche</span> si la glande ne fonctionne pas (thyroïdite, factice), <span class=\"kw-imagerie\">fixante</span> si elle hyperfonctionne.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":1},{"id":"242-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l’hyperthyroïdie","contenu":"<ul>\n        <li><span class=\"kw-def\">Prévalence</span> <strong>élevée mais variable</strong> selon les pays : <span class=\"kw-chiffre\">0,2 à 1,9 %</span> de la population, toutes causes confondues.</li>\n        <li>Nette <strong>prédominance féminine</strong> : sex-ratio <span class=\"kw-chiffre\">7 femmes / 1 homme</span>.</li>\n        <li>La <span class=\"kw-etio\">maladie de Basedow</span> touche <span class=\"kw-chiffre\">~1 %</span> de la population (<span class=\"kw-chiffre\">1,9 %</span> des femmes, <span class=\"kw-chiffre\">0,4 %</span> des hommes) — c'est la cause la plus fréquente d'<span class=\"kw-def\">hyperthyroïdie</span> chez la <strong>femme jeune</strong>.</li>\n      </ul>","frequence":0},{"id":"242-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une hyperthyroïdie","contenu":"<p>Le <span class=\"kw-def\">syndrome de thyrotoxicose</span> est <strong>multi-organe</strong> ; son intensité dépend du degré, de la durée et du <span class=\"kw-def\">terrain</span>.</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Poids</th>\n            <td><span class=\"kw-clinique\">Amaigrissement</span> rapide, souvent important, contrastant avec un <strong>appétit conservé ou augmenté</strong> (<span class=\"kw-clinique\">polyphagie</span>) ; <span class=\"kw-clinique\">amyotrophie</span> des racines avec baisse de force (<strong>signe du tabouret</strong>).</td>\n          </tr>\n          <tr>\n            <th>Thermorégulation</th>\n            <td><span class=\"kw-clinique\">Thermophobie</span> ; <span class=\"kw-clinique\">hyperthermie</span> ; <span class=\"kw-clinique\">hypersudation</span> (mains chaudes et moites) ; <span class=\"kw-clinique\">polydipsie</span>.</td>\n          </tr>\n          <tr>\n            <th>Cardiovasculaire</th>\n            <td><span class=\"kw-clinique\">Tachycardie</span> régulière, sinusale, persistant au repos ; <span class=\"kw-clinique\">palpitations</span> ; <span class=\"kw-clinique\">dyspnée</span> d'effort ; éréthisme cardiaque ; pouls vibrant ; élévation de la PAS ; parfois <span class=\"kw-alerte\">fibrillation auriculaire</span>.</td>\n          </tr>\n          <tr>\n            <th>Neuropsychique</th>\n            <td><span class=\"kw-clinique\">Tremblement</span> fin et régulier des extrémités ; nervosité, agitation psychomotrice, labilité de l'humeur ; troubles du sommeil.</td>\n          </tr>\n          <tr>\n            <th>Digestif</th>\n            <td><span class=\"kw-clinique\">Polyexonération</span> (<span class=\"kw-clinique\">diarrhée</span> motrice) par accélération du transit.</td>\n          </tr>\n          <tr>\n            <th>Ophtalmo (non spé)</th>\n            <td><strong>Éclat du regard</strong> possible <em>quelle que soit la cause</em> de l'excès d'hormones thyroïdiennes (LiSA).</td>\n          </tr>\n          <tr>\n            <th>Ophtalmo (spé Basedow)</th>\n            <td>3 signes spécifiques : <span class=\"kw-clinique\">rétraction de la paupière supérieure</span> découvrant l'iris avec <strong>asynergie oculopalpébrale</strong> et parfois <strong>rougeur conjonctivale</strong> ; <span class=\"kw-clinique\">exophtalmie</span> ; <strong>œdème palpébral</strong>.</td>\n          </tr>\n          <tr>\n            <th>Plus rares</th>\n            <td>Gynécomastie chez l'homme ; troubles des règles chez la femme (<strong>fertilité conservée</strong>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Principaux signes par <strong>ordre de fréquence</strong> :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-clinique\">Tachycardie</span> de repos</th><td><span class=\"kw-chiffre\">96 %</span></td></tr>\n          <tr><th>Nervosité</th><td><span class=\"kw-chiffre\">93 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Asthénie</span></th><td><span class=\"kw-chiffre\">88 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Palpitations</span></th><td><span class=\"kw-chiffre\">86 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Amaigrissement</span> avec <span class=\"kw-clinique\">polyphagie</span></th><td><span class=\"kw-chiffre\">83 %</span></td></tr>\n          <tr><th>Thermophobie</th><td><span class=\"kw-chiffre\">82 %</span></td></tr>\n          <tr><th>Hypersudation</th><td><span class=\"kw-chiffre\">80 %</span></td></tr>\n          <tr><th>Tremblement</th><td><span class=\"kw-chiffre\">73 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Dyspnée</span> d'effort</th><td><span class=\"kw-chiffre\">73 %</span></td></tr>\n          <tr><th>Fatigabilité musculaire, amyotrophie</th><td><span class=\"kw-chiffre\">70 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Polydipsie</span></th><td><span class=\"kw-chiffre\">48 %</span></td></tr>\n          <tr><th>Polyexonération</th><td><span class=\"kw-chiffre\">35 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Prurit</span></th><td><span class=\"kw-chiffre\">18 %</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Œdème</span> des membres inférieurs</th><td><span class=\"kw-chiffre\">13 %</span></td></tr>\n          <tr><th><span class=\"kw-def\">Fibrillation auriculaire</span></th><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">asthénie</span> et <span class=\"kw-clinique\">dysménorrhée</span> sont des manifestations <strong>communes avec l'<span class=\"kw-def\">hypothyroïdie</span></strong> — non discriminantes à elles seules.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 237 — <span class=\"kw-clinique\">Palpitations</span> · 232 — <span class=\"kw-def\">Fibrillation atriale</span></em></p>","frequence":2},{"id":"242-4","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques évocateurs d’une crise aiguë thyrotoxique","contenu":"<p>La <span class=\"kw-alerte\">crise aiguë thyrotoxique</span> est une <strong><span class=\"kw-alerte\">urgence</span> vitale exceptionnelle</strong> mais redoutable.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong>\n        <ul>\n          <li><strong>Contexte :</strong> survient surtout <span class=\"kw-alerte\">après thyroïdectomie en l'absence de préparation médicale</span> par antithyroïdiens de synthèse.</li>\n          <li><strong>Présentation :</strong> exacerbation du <span class=\"kw-clinique\">syndrome de thyrotoxicose</span> + <span class=\"kw-alerte\">fièvre</span> + <span class=\"kw-alerte\">déshydratation</span> + troubles <span class=\"kw-alerte\">cardiovasculaires</span> et <span class=\"kw-alerte\">neuropsychiques</span>, pouvant mettre en jeu le <span class=\"kw-alerte\">pronostic vital</span>.</li>\n          <li><strong>Orientation :</strong> <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">unité de soins intensifs</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 232 — <span class=\"kw-def\">Fibrillation atriale</span></em></p>","frequence":0},{"id":"242-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les complications possibles de l’ophtalmopathie dysthyroïdienne : neuropathie optique compressive, kératite d’exposition","contenu":"<p>L'<span class=\"kw-def\">orbitopathie maligne</span> est la forme compliquée de l'ophtalmopathie dysthyroïdienne — elle <strong><span class=\"kw-alerte\">menace</span> le <span class=\"kw-def\">pronostic</span> visuel</strong>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Signes d'alerte.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Exophtalmie &gt; 25 mm</span>, douloureuse et <strong>irréductible</strong>.</li>\n          <li><span class=\"kw-alerte\">Lagophtalmie</span> (inocclusion palpébrale).</li>\n          <li><span class=\"kw-alerte\">Diminution de l'acuité visuelle</span>.</li>\n        </ul>\n      </div>\n      <p>Les deux complications à connaître (citées dans l'intitulé EDN) :</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Kératite d'exposition</th>\n            <td>Atteinte cornéenne par <strong>sécheresse</strong> (liée à la lagophtalmie) : <span class=\"kw-clinique\">kératite</span>, <span class=\"kw-clinique\">ulcération</span>, voire <span class=\"kw-alerte\">perforation cornéenne</span>.</td>\n          </tr>\n          <tr>\n            <th>Neuropathie optique compressive</th>\n            <td><span class=\"kw-chiffre\">~3 %</span> des cas. Compression du nerf optique par l'hypertrophie des muscles à <strong>l'apex orbitaire</strong> ou par hyperpression orbitaire → altérations du champ visuel pouvant aller jusqu'à la <span class=\"kw-alerte\">cécité</span>.</td>\n          </tr>\n          <tr>\n            <th>Atteinte musculaire péri-orbitaire</th>\n            <td>Phénomènes œdémateux et inflammatoires puis <strong>fibrose musculaire</strong> → <span class=\"kw-clinique\">diplopie</span> (LiSA — 3ᵉ complication de l'ophtalmopathie).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Conduite à tenir.</strong> <span class=\"kw-def\">Pronostic</span> visuel en jeu : consultation <span class=\"kw-alerte\">ophtalmologique en urgence (&lt; 48 h)</span> → <span class=\"kw-ttt\">bolus de méthylprednisolone</span> à forte dose et/ou <span class=\"kw-ttt\">décompression orbitaire</span> rapide.\n      </div>","frequence":2},{"id":"242-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’interprétation des dosages hormonaux","contenu":"<p>La stratégie suit une <strong>cascade</strong> (modification UNCAM de mai 2024, alignée sur les recommandations HAS) : on ne demande pas tout d'emblée.</p>\n      <table >\n        <thead><tr><th>Dosage</th><th>Place &amp; interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-bio\">TSH</span></th>\n            <td><strong>1ʳᵉ intention</strong>, seule à demander d'emblée. <span class=\"kw-bio\">Constamment effondrée</span> dans l'<span class=\"kw-def\">hyperthyroïdie</span> périphérique.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">T4 libre</span></th>\n            <td><strong>2ⁿᵈ intention</strong>, si la <span class=\"kw-bio\">TSH</span> est basse : apprécie l'<strong>importance</strong> de la thyrotoxicose.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">T3 libre</span></th>\n            <td><strong>3ᵉ intention</strong> : n'a d'intérêt <span class=\"kw-alerte\">que si la T4L est normale</span>, pour dépister une <span class=\"kw-bio\">hyperthyroïdie à T3</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Exception — <span class=\"kw-bio\">TSH</span> inadaptée.</strong> Si la <span class=\"kw-bio\">TSH</span> est <span class=\"kw-alerte\">normale ou élevée</span> malgré une <span class=\"kw-bio\">T4L</span> élevée, évoquer un <span class=\"kw-etio\">adénome thyréotrope</span> ou un <span class=\"kw-etio\">syndrome de résistance aux hormones thyroïdiennes</span> (<span class=\"kw-def\">hyperthyroïdie</span> d'origine centrale).\n      </div>\n      <ul>\n        <li>Un <strong>contrôle</strong> de la <span class=\"kw-bio\">TSH</span> se fait au minimum à <span class=\"kw-chiffre\">6 semaines</span> d'intervalle.</li>\n        <li>En <span class=\"kw-def\">suivi</span> initial d'un traitement par antithyroïdiens de synthèse, les dosages sont espacés d'au moins <span class=\"kw-chiffre\">8 semaines</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Distinction LiSA — fruste vs franche.</strong>\n        <ul>\n          <li><span class=\"kw-def\">Hyperthyroïdie fruste</span> (ou <span class=\"kw-def\">infra-clinique</span>) : <span class=\"kw-bio\">TSH basse</span> avec <strong>hormones périphériques normales</strong> (T4L et T3L).</li>\n          <li><span class=\"kw-def\">Hyperthyroïdie franche</span> : <span class=\"kw-bio\">TSH basse</span> avec <strong>élévation des hormones périphériques</strong>.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège de <span class=\"kw-def\">suivi</span>.</strong> Sous traitement, la <span class=\"kw-bio\">TSH peut rester basse longtemps</span> par <strong>inertie thyréotrope</strong> : on juge l'efficacité initiale sur la <span class=\"kw-bio\">T4 libre</span> (3ᵉ–4ᵉ semaine), pas sur la <span class=\"kw-bio\">TSH</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":4},{"id":"242-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes biologiques spécifiques (anticorps anti-récepteurs de TSH) et non spécifiques","contenu":"<p><strong>Signe spécifique</strong> — les <span class=\"kw-bio\">anticorps anti-récepteurs de la TSH (TRAK)</span> : leur positivité signe la <span class=\"kw-etio\">maladie de Basedow</span>.</p>\n      <p><strong>Signes non spécifiques</strong> — perturbations inconstantes, mais qui peuvent révéler la maladie :</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Anomalie</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-bio\">NFS</span></th>\n            <td><span class=\"kw-bio\">Leuconeutropénie</span> avec lymphocytose relative.</td>\n          </tr>\n          <tr>\n            <th>Métabolique</th>\n            <td>Baisse du <span class=\"kw-bio\">cholestérol</span> et des <span class=\"kw-bio\">triglycérides</span> ; discrète <span class=\"kw-bio\">hyperglycémie</span> (stimulation de la néoglucogenèse) ; <strong>aggravation d'un diabète associé</strong> (LiSA).</td>\n          </tr>\n          <tr>\n            <th>Enzymes</th>\n            <td>Élévation des <span class=\"kw-bio\">enzymes hépatiques</span> (transaminases et <span class=\"kw-bio\">GGT</span>).</td>\n          </tr>\n          <tr>\n            <th>Phosphocalcique</th>\n            <td><span class=\"kw-bio\">Hypercalcémie</span> modérée dans <span class=\"kw-chiffre\">15–20 %</span> des cas.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span></em></p>","frequence":1},{"id":"242-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de la scintigraphie thyroïdienne et de l’échographie","contenu":"<p>Ces examens sont à <strong>visée étiologique</strong> — ils ne confirment pas l'<span class=\"kw-def\">hyperthyroïdie</span> (c'est le rôle de la <span class=\"kw-bio\">TSH</span>).</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications &amp; apport</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\">Scintigraphie</span> thyroïdienne</th>\n            <td>Iode 123 ou technétium 99. Indiquée devant un <strong><span class=\"kw-clinique\">nodule</span></strong> ou un <strong>goitre plurinodulaire</strong>. Devant un goitre diffus chez un sujet jeune, on privilégie d'abord les <span class=\"kw-bio\">TRAK</span>.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">Échographie</span></th>\n            <td>Apprécie le volume, l'échostructure (aspect <span class=\"kw-imagerie\">hypoéchogène</span>), la vascularisation. <strong>Alternative</strong> à la <span class=\"kw-imagerie\">scintigraphie</span>, notamment en cas de <span class=\"kw-ci\">grossesse</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Aspects scintigraphiques selon l'étiologie :</p>\n      <table >\n        <thead><tr><th>Aspect</th><th>Étiologie</th></tr></thead>\n        <tbody>\n          <tr><th>Hyperfixation diffuse et homogène</th><td><span class=\"kw-etio\">Maladie de Basedow</span></td></tr>\n          <tr><th>Alternance plages fixantes / hypofixantes (« damier »)</th><td><span class=\"kw-etio\">Goitre multinodulaire toxique</span></td></tr>\n          <tr><th><span class=\"kw-clinique\">Nodule</span> extinctif (seul fixant), tissu sain freiné</th><td><span class=\"kw-etio\">Adénome toxique</span></td></tr>\n          <tr><th><span class=\"kw-imagerie\">Scintigraphie</span> blanche (aucune fixation)</th><td><span class=\"kw-etio\">Thyroïdite</span>, <span class=\"kw-etio\">thyrotoxicose factice</span>, surcharge iodée de type 2</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 241 — Goitre - <span class=\"kw-clinique\">nodule</span> - cancer thyroïdien</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/thyroid-gland","label":"Radiopaedia : Thyroid gland"},{"href":"https://radiopaedia.org/articles/postpartum-thyroiditis-2","label":"Radiopaedia : Postpartum thyroiditis 2"},{"href":"https://radiopaedia.org/articles/de-quervain-thyroiditis","label":"Radiopaedia : De quervain thyroiditis"},{"href":"https://radiopaedia.org/articles/multinodular-goiter-1","label":"Radiopaedia : Multinodular goiter 1"},{"href":"https://radiopaedia.org/cases/toxic-thyroid-adenoma-1","label":"Radiopaedia : Toxic thyroid adenoma 1"},{"href":"https://radiopaedia.org/articles/hashimoto-thyroiditis","label":"Radiopaedia : Hashimoto thyroiditis"},{"href":"https://radiopaedia.org/articles/parathyroid-glands","label":"Radiopaedia : Parathyroid glands"},{"href":"https://radiopaedia.org/articles/graves-disease","label":"Radiopaedia : Graves disease"},{"href":"https://radiopaedia.org/articles/thyroid-associated-orbitopathy-1","label":"Radiopaedia : Thyroid associated orbitopathy 1"}]},{"id":"242-9","rang":"A","rubrique":"Etiologies","titre":"Connaître les trois étiologies les plus fréquentes d’hyperthyroïdie","contenu":"<p>Les <strong>trois causes les plus fréquentes</strong> d'<span class=\"kw-def\">hyperthyroïdie</span> :</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th><span class=\"kw-def\">Terrain</span> typique</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Maladie de Basedow</th>\n            <td>Cause <span class=\"kw-etio\">auto-immune</span> ; 1ʳᵉ cause chez la <strong>femme jeune</strong>.</td>\n          </tr>\n          <tr>\n            <th>Goitre multinodulaire <span class=\"kw-etio\">toxique</span></th>\n            <td>1ʳᵉ cause chez le <strong>sujet âgé</strong>.</td>\n          </tr>\n          <tr>\n            <th>Adénome <span class=\"kw-etio\">toxique</span></th>\n            <td><span class=\"kw-clinique\">Nodule</span> <strong>unique</strong> hypersécrétant, autonome.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Autres causes</strong> (à connaître mais hors « top 3 ») : <span class=\"kw-etio\">thyroïdites</span> (subaiguë de De Quervain, du post-partum, Hashimoto à sa phase initiale), <span class=\"kw-etio\">hyperthyroïdies iatrogènes</span> (surcharge iodée, <span class=\"kw-ttt\">amiodarone</span>), <span class=\"kw-etio\">thyrotoxicose gestationnelle transitoire</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":1},{"id":"242-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques d’une maladie de Basedow","contenu":"<p>La <span class=\"kw-etio\">maladie de Basedow</span> est une maladie <strong><span class=\"kw-etio\">auto-immune</span></strong> due aux <span class=\"kw-bio\">anticorps anti-récepteurs de la TSH (TRAK)</span>, stimulants : ils activent la production hormonale et agissent aussi sur les muscles oculomoteurs et la graisse orbitaire.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-def\">Terrain</span></th>\n            <td>Femme jeune <span class=\"kw-chiffre\">20–40 ans</span> ; sex-ratio <span class=\"kw-chiffre\">5–7 F / 1 H</span> ; <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">auto-immun</span> personnel ou familial.</td>\n          </tr>\n          <tr>\n            <th>Triade clinique</th>\n            <td><span class=\"kw-clinique\">Syndrome de thyrotoxicose</span> ; <span class=\"kw-clinique\">orbitopathie dysthyroïdienne</span> (<span class=\"kw-chiffre\">25–50 %</span> des Basedow) ; <span class=\"kw-clinique\">goitre</span> diffus, homogène, élastique, <strong>vasculaire</strong> (<span class=\"kw-clinique\">souffle systolique</span> à l'auscultation de la thyroïde).</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Évolution</span></th>\n            <td>Épisode unique (<span class=\"kw-chiffre\">40–50 %</span>) ou récidivant de façon cyclique (<span class=\"kw-chiffre\">50–60 %</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Démarche diagnostique :</strong></p>\n      <ul>\n        <li>Devant l'association <strong>hyperthyroïdie + orbitopathie</strong>, le diagnostic est <span class=\"kw-def\">évoqué cliniquement</span> (<strong>consensus SFE 2016</strong>).</li>\n        <li>Sinon : <span class=\"kw-bio\">TRAK en 1ʳᵉ intention</span> (un titre élevé confirme le diagnostic).</li>\n        <li>En 2ⁿᵈ intention : <span class=\"kw-imagerie\">scintigraphie</span> (hyperfixation diffuse et homogène) ou <span class=\"kw-imagerie\">échographie</span> (glande globalement hypoéchogène et très vascularisée — alternative, notamment en cas de <span class=\"kw-ci\">grossesse</span>).</li>\n      </ul>","frequence":3},{"id":"242-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques d’un nodule hypersécrétant","contenu":"<p>Deux entités, toutes deux marquées par un <span class=\"kw-clinique\">syndrome de thyrotoxicose pur</span> (<strong>sans atteinte oculaire</strong>) :</p>\n      <table >\n        <thead><tr><th>Entité</th><th><span class=\"kw-def\">Critères diagnostiques</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Adénome <span class=\"kw-etio\">toxique</span></th>\n            <td>\n              <strong>Clinique :</strong> <span class=\"kw-clinique\">nodule</span> <span class=\"kw-clinique\">unique</span> ; thyrotoxicose pure<br>\n              <strong><span class=\"kw-imagerie\">Scintigraphie</span> :</strong> <span class=\"kw-imagerie\">nodule extinctif</span> (seul fixant) avec <span class=\"kw-imagerie\">tissu sain freiné</span> — examen nécessaire au diagnostic<br>\n              <strong><span class=\"kw-imagerie\">Échographie</span> :</strong> nodule tissulaire ou partiellement kystique\n            </td>\n          </tr>\n          <tr>\n            <th>Goitre multinodulaire <span class=\"kw-etio\">toxique</span></th>\n            <td>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> 1ʳᵉ cause d'<span class=\"kw-def\">hyperthyroïdie</span> du <span class=\"kw-clinique\">sujet âgé</span><br>\n              <strong>Clinique :</strong> goitre multinodulaire ; thyrotoxicose pure<br>\n              <strong><span class=\"kw-imagerie\">Scintigraphie</span> :</strong> alternance de plages fixantes et hypofixantes en <span class=\"kw-imagerie\">« damier »</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Devant un <span class=\"kw-clinique\">nodule</span> thyroïdien avec une <span class=\"kw-bio\">TSH basse</span>, on ne réalise <strong>pas de cytoponction</strong> — même si le nodule est volumineux, irrégulier ou <span class=\"kw-imagerie\">hypoéchogène</span>. La <span class=\"kw-bio\">TSH</span> basse signe son caractère fonctionnel (bénin).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 241 — Goitre - <span class=\"kw-clinique\">nodule</span> - cancer thyroïdien</em></p>","frequence":0},{"id":"242-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques d’une hyperthyroïdie iatrogène","contenu":"<p>Trois grands mécanismes d'<span class=\"kw-etio\">hyperthyroïdie iatrogène</span> :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Surcharge iodée</th>\n            <td><span class=\"kw-ttt\">Produits de contraste iodés</span> (saturation thyroïdienne en iode <span class=\"kw-chiffre\">4 à 6 semaines</span>, hyperthyroïdie souvent transitoire et peu symptomatique) ; <span class=\"kw-ttt\">amiodarone</span> (<span class=\"kw-chiffre\">75 mg</span> d'iode/cp ; <strong>saturation prolongée <span class=\"kw-chiffre\">9 à 12 mois</span></strong> ; dysthyroïdie chez <span class=\"kw-chiffre\">~10 %</span> des patients traités).</td>\n          </tr>\n          <tr>\n            <th>Immunomodulateurs</th>\n            <td><span class=\"kw-ttt\">Interféron</span>, <span class=\"kw-ttt\">immunothérapie</span> anti-checkpoint : <span class=\"kw-def\">thyroïdite</span> avec phase initiale d'<span class=\"kw-def\">hyperthyroïdie</span>, <strong>souvent suivie d'une phase d'hypothyroïdie parfois définitive</strong> (LiSA).</td>\n          </tr>\n          <tr>\n            <th>Hormones thyroïdiennes</th>\n            <td>Surdosage d'un traitement substitutif ; <span class=\"kw-etio\">thyrotoxicose factice</span> (prise cachée à visée d'<span class=\"kw-clinique\">amaigrissement</span>) : <strong>pas de goitre</strong>, <span class=\"kw-imagerie\">scintigraphie blanche</span>, <span class=\"kw-bio\">thyroglobuline effondrée</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Pour la surcharge iodée, distinguer <strong>deux types</strong> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Type 1 — fonctionnelle</th>\n            <td>Apport brutal d'iode sur une thyroïde <span class=\"kw-etio\">nodulaire préexistante</span> ; <span class=\"kw-imagerie\">échographie</span> hypervascularisée ; prise en charge par <span class=\"kw-ttt\">antithyroïdiens de synthèse</span>.</td>\n          </tr>\n          <tr>\n            <th>Type 2 — lésionnelle</th>\n            <td>Effet <span class=\"kw-etio\">toxique</span> de l'iode → <span class=\"kw-etio\">thyroïdite</span> par lyse ; thyroïde d'aspect normal, hypoéchogène homogène ; <span class=\"kw-imagerie\">scintigraphie blanche</span> ; prise en charge par <span class=\"kw-ttt\">corticoïdes</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant <span class=\"kw-ttt\">amiodarone</span>.</strong> Le profil thyroïdien <em>normal</em> sous <span class=\"kw-ttt\">amiodarone</span> associe <span class=\"kw-bio\">T4L élevée</span> + <span class=\"kw-bio\">T3L normale</span> + <span class=\"kw-bio\">TSH normale</span> — à ne pas confondre avec une vraie <span class=\"kw-def\">hyperthyroïdie</span>, où la <span class=\"kw-bio\">TSH</span> est effondrée.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span class=\"kw-def\">Fibrillation atriale</span> · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"242-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique d’une hyperthyroïdie","contenu":"<p><strong>Orientation</strong> — les thyrotoxicoses sont traitées en <span class=\"kw-clinique\">ambulatoire</span> ; une <span class=\"kw-alerte\">hospitalisation</span> s'impose en cas d'orbitopathie maligne, de crise aiguë thyrotoxique, de forme cachectisante du vieillard ou de cardiothyréose.</p>\n      <p><strong>Mesures non spécifiques :</strong></p>\n      <ul>\n        <li>Repos, arrêt de travail selon le retentissement.</li>\n        <li><span class=\"kw-ttt\">Contraception efficace</span> chez la femme en âge de procréer.</li>\n        <li><span class=\"kw-ttt\">β-bloquant</span> (<span class=\"kw-ttt\">propranolol</span>, non cardiosélectif, <strong>après avoir éliminé toute CI</strong>) : réduit la <span class=\"kw-clinique\">tachycardie</span> <strong>et</strong> les tremblements, action rapide en attendant l'effet des traitements spécifiques.</li>\n        <li><span class=\"kw-ttt\">Sédatifs</span> ou <span class=\"kw-ttt\">benzodiazépines</span> en cas de troubles du comportement (agitation) ou d'insomnie invalidante (LiSA).</li>\n      </ul>\n      <p><strong>Trois traitements spécifiques :</strong></p>\n      <table >\n        <thead><tr><th>Traitement</th><th>Principes</th><th>Limites</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Antithyroïdiens de synthèse (ATS)</th>\n            <td>\n              <strong>Molécules :</strong> méthimazole, carbimazole ; thio-uraciles (si <span class=\"kw-ci\">intolérance</span> ou <span class=\"kw-ci\">grossesse</span>)<br>\n              <strong>Mécanisme :</strong> blocage de la thyroperoxydase ; n'agissent pas sur les hormones déjà stockées → <span class=\"kw-chiffre\">délai d'action 10–15 j</span><br>\n              <strong>Durée (Basedow) :</strong> <span class=\"kw-chiffre\">12 à 18 mois</span>\n            </td>\n            <td><span class=\"kw-ci\">CI :</span> <span class=\"kw-ci\">grossesse</span>, insuffisance hépatique, hémopathie sévère. Rechute dans <span class=\"kw-chiffre\">40–60 %</span> des cas.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-ttt\">Chirurgie</span></th>\n            <td>\n              <strong>Modalités :</strong> thyroïdectomie totale (Basedow, goitre multinodulaire <span class=\"kw-etio\">toxique</span>) ou lobectomie (adénome toxique)<br>\n              <strong>Préparation :</strong> ATS pendant <span class=\"kw-chiffre\">2–3 mois</span> pour obtenir l'euthyroïdie (prévention de la crise aiguë thyrotoxique)\n            </td>\n            <td>Complications (<span class=\"kw-chiffre\">1–3 %</span>) : <span class=\"kw-alerte\">hématome suffocant</span>, <span class=\"kw-def\">hypothyroïdie</span> définitive, paralysie récurrentielle, hypoparathyroïdie.</td>\n          </tr>\n          <tr>\n            <th>Radio-iode 131</th>\n            <td>\n              <strong>Principe :</strong> traitement non invasif, en ambulatoire<br>\n              <strong>Délai d'action :</strong> <span class=\"kw-chiffre\">1 à 3 mois</span>\n            </td>\n            <td><span class=\"kw-ci\">CI :</span> <span class=\"kw-ci\">grossesse</span>, allaitement, <strong>orbitopathie évolutive / sévère / très inflammatoire</strong> (LiSA). Contraception <span class=\"kw-chiffre\">6–12 mois</span> après. Aboutit à une <span class=\"kw-alerte\">hypothyroïdie définitive</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Avantages et inconvénients comparés :</p>\n      <table >\n        <thead><tr><th>Traitement</th><th>Avantages</th><th>Inconvénients</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>ATS</th>\n            <td>Non invasif ; rémission <span class=\"kw-chiffre\">40–50 %</span> ; coût faible.</td>\n            <td>Taux de rechute élevé ; traitement long.</td>\n          </tr>\n          <tr>\n            <th>Iode 131</th>\n            <td>Non invasif ; efficace ; faible taux de récidive.</td>\n            <td>Délai d'action ; <span class=\"kw-alerte\">hypothyroïdie définitive</span> ; risque d'aggravation de l'orbitopathie.</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-ttt\">Chirurgie</span></th>\n            <td>Rapidité d'effet ; efficacité.</td>\n            <td>Complications postopératoires ; <span class=\"kw-alerte\">hypothyroïdie définitive</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Prise en charge de l'orbitopathie</strong> (selon le <span class=\"kw-def\">stade</span>) :</p>\n      <table >\n        <thead><tr><th>Stade</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><th>Tous stades</th><td>Restauration de l'euthyroïdie ; <span class=\"kw-ttt\">arrêt du tabac</span> (essentiel) ; protection de la cornée (substituts lacrymaux) ; verres teintés, prismes.</td></tr>\n          <tr><th>Formes minimes</th><td><span class=\"kw-def\">Surveillance</span>.</td></tr>\n          <tr><th>Formes moyennes</th><td><span class=\"kw-ttt\">Corticothérapie orale</span> et/ou <span class=\"kw-ttt\">radiothérapie</span> orbitaire.</td></tr>\n          <tr><th>Formes sévères (CAS <span class=\"kw-chiffre\">≥ 3</span>)</th><td><span class=\"kw-ttt\">Bolus de méthylprednisolone IV</span> ou <span class=\"kw-ttt\">décompression orbitaire</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — agranulocytose sous ATS.</strong> <span class=\"kw-def\">Dépistage</span> par <span class=\"kw-bio\">NFS régulière</span> les 2 premiers mois ; <span class=\"kw-bio\">NFS</span> immédiate en cas de <span class=\"kw-alerte\">fièvre ou angine</span>. Si <span class=\"kw-bio\">PNN &lt; 0,5 G/L</span> : <strong>arrêt définitif des ATS</strong> + <span class=\"kw-alerte\">hospitalisation</span> en milieu protégé + <span class=\"kw-ttt\">antibiothérapie</span> à large spectre.\n      </div>\n      <p><strong>Cas particulier — femme enceinte</strong> (LiSA) :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Maladie de Basedow</span> et grossesse : prise en charge <strong>spécialisée</strong> (indication d'<span class=\"kw-ttt\">ATS à faible dose</span>, limitation de la tératogénicité, modalités de surveillance) — <strong>rémissions spontanées fréquentes en 2ᵉ partie de grossesse</strong>.</li>\n        <li><strong>DD clé à connaître : <span class=\"kw-etio\">thyrotoxicose gestationnelle transitoire</span></strong> — plus fréquente que Basedow pendant la grossesse (<span class=\"kw-chiffre\">2 %</span> des grossesses), <span class=\"kw-bio\">TRAK négatifs</span>, hyperthyroïdie <strong>ponctuelle au 1ᵉʳ trimestre</strong>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 296 — Agranulocytose médicamenteuse · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> la <span class=\"kw-def\">thyrotoxicose</span> est le plus souvent traitée en <span class=\"kw-ttt\">ambulatoire</span>, mais quelques situations engagent le <span class=\"kw-alerte\">pronostic vital</span> ou visuel.<br><strong>Crise aiguë thyrotoxique :</strong> <span class=\"kw-alerte\">urgence vitale</span> → <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">unité de soins intensifs</span> (survient surtout après <span class=\"kw-ttt\">thyroïdectomie</span> sans préparation).<br><strong>Orbitopathie maligne :</strong> <span class=\"kw-def\">pronostic</span> visuel en jeu → avis <span class=\"kw-ttt\">ophtalmologique</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">< 48h</span>) + bolus de <span class=\"kw-ttt\">méthylprednisolone</span> forte dose ± <span class=\"kw-ttt\">décompression orbitaire</span>.<br><strong>Agranulocytose sous ATS :</strong> <span class=\"kw-bio\">NFS</span> immédiate si <span class=\"kw-clinique\">fièvre</span> ou <span class=\"kw-clinique\">angine</span> ; <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">< 0,5 G/L</span> → hospitalisation et arrêt définitif des <span class=\"kw-ttt\">ATS</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> prise en charge de la majorité des <span class=\"kw-def\">thyrotoxicoses</span>, y compris le <span class=\"kw-ttt\">radio-iode 131</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> réservée à l'<span class=\"kw-etio\">orbitopathie maligne</span>, la <span class=\"kw-alerte\">crise aiguë thyrotoxique</span> (<span class=\"kw-alerte\">soins intensifs</span>), la <span class=\"kw-etio\">forme cachectisante du vieillard</span> et la <span class=\"kw-etio\">cardiothyréose</span>.<br><strong>Milieu protégé :</strong> <span class=\"kw-etio\">agranulocytose</span> sous <span class=\"kw-ttt\">ATS</span> avec <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">< 0,5 G/L</span>.<br><strong>Milieu spécialisé :</strong> grossesse chez une femme <span class=\"kw-etio\">hyperthyroïdienne</span> (suivi conjoint de la mère et du fœtus).</p>","redflags":"<ul><li><span class=\"kw-etio\">Crise aiguë thyrotoxique</span> : exacerbation de la thyrotoxicose + <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">déshydratation</span> + troubles <span class=\"kw-clinique\">cardiovasculaires</span> et <span class=\"kw-clinique\">neuropsychiques</span> mettant en jeu le <span class=\"kw-alerte\">pronostic vital</span></li><li><span class=\"kw-etio\">Cardiothyréose</span> chez le sujet âgé/fragile : <span class=\"kw-clinique\">fibrillation auriculaire</span>, <span class=\"kw-etio\">insuffisance cardiaque</span> à prédominance droite, aggravation d'une <span class=\"kw-etio\">insuffisance coronaire</span></li><li><span class=\"kw-etio\">Orbitopathie maligne</span> : <span class=\"kw-clinique\">exophtalmie</span> <span class=\"kw-chiffre\">> 25 mm</span> douloureuse et irréductible, <span class=\"kw-clinique\">lagophtalmie</span>, <span class=\"kw-alerte\">diminution de l'acuité visuelle</span> (<span class=\"kw-etio\">neuropathie optique compressive</span>, <span class=\"kw-etio\">kératite d'exposition</span>)</li><li><span class=\"kw-etio\">Agranulocytose</span> sous <span class=\"kw-ttt\">ATS</span> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">angine</span>, <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">< 0,5 G/L</span> → risque infectieux majeur</li><li><span class=\"kw-etio\">Forme cachectisante du vieillard</span> : <span class=\"kw-clinique\">altération de l'état général</span>, fonte musculaire, <span class=\"kw-clinique\">cachexie</span></li></ul>","principes":"<p>Aucun traitement n'agit sur la cause : on associe un volet <span class=\"kw-ttt\">symptomatique</span> d'action rapide et un volet spécifique choisi selon l'étiologie et le <span class=\"kw-def\">terrain</span>.</p><p><strong>Mesures non spécifiques (symptomatiques)</strong></p><ul><li><span class=\"kw-ttt\">β-bloquant</span> (<span class=\"kw-ttt\">propranolol</span>, non cardiosélectif) : réduit la <span class=\"kw-clinique\">tachycardie</span> et les <span class=\"kw-clinique\">tremblements</span>, action rapide en attendant l'effet du traitement spécifique</li><li>Repos, arrêt de travail selon le retentissement</li><li><span class=\"kw-ttt\">Contraception efficace</span> chez la femme en âge de procréer (effet <span class=\"kw-ci\">tératogène</span> des <span class=\"kw-ttt\">ATS</span> et de l'<span class=\"kw-ttt\">iode 131</span>)</li></ul><p><strong>Antithyroïdiens de synthèse (ATS) — 1re intention</strong></p><p>Dépister l'<span class=\"kw-etio\">agranulocytose</span> : <span class=\"kw-bio\">NFS</span> tous les <span class=\"kw-chiffre\">10 jours</span> les <span class=\"kw-chiffre\">2 premiers mois</span> et en <span class=\"kw-alerte\">urgence</span> si <span class=\"kw-clinique\">fièvre</span>/<span class=\"kw-clinique\">angine</span></p><ul><li>Molécules : <span class=\"kw-ttt\">méthimazole</span> / <span class=\"kw-ttt\">carbimazole</span> ; <span class=\"kw-ttt\">thio-uraciles</span> (propylthio-uracile) si <span class=\"kw-ci\">grossesse</span> ou <span class=\"kw-ci\">intolérance</span></li><li>Délai d'action de <span class=\"kw-chiffre\">10-15 jours</span> (n'agissent pas sur les hormones déjà stockées) ; posologie initiale forte pendant <span class=\"kw-chiffre\">4-6 semaines</span></li><li>Durée dans la <span class=\"kw-etio\">maladie de Basedow</span> : <span class=\"kw-chiffre\">12 à 18 mois</span></li><li><span class=\"kw-ci\">Contre-indications</span> : <span class=\"kw-ci\">grossesse</span> (méthimazole au 1er trimestre), <span class=\"kw-ci\">insuffisance hépatique</span>, <span class=\"kw-ci\">hémopathie sévère</span></li></ul><p><strong>Traitement radical (rechute, échec, cardiothyréose)</strong></p><ul><li>Toujours précédé d'une préparation par <span class=\"kw-ttt\">ATS</span> pendant <span class=\"kw-chiffre\">2-3 mois</span> pour obtenir l'<span class=\"kw-def\">euthyroïdie</span> (prévention de la <span class=\"kw-alerte\">crise aiguë thyrotoxique</span>)</li><li><span class=\"kw-ttt\">Thyroïdectomie totale</span> : <span class=\"kw-etio\">Basedow</span>, <span class=\"kw-etio\">goitre multinodulaire toxique</span> ; <span class=\"kw-ttt\">lobectomie</span> pour l'<span class=\"kw-etio\">adénome toxique</span></li><li><span class=\"kw-ttt\">Radio-iode 131</span> : ambulatoire, plutôt sujet âgé/fragile ; délai <span class=\"kw-chiffre\">1-3 mois</span> ; <span class=\"kw-ci\">grossesse</span> et <span class=\"kw-ci\">allaitement</span> <span class=\"kw-ci\">contre-indiqués</span> ; conduit à une <span class=\"kw-etio\">hypothyroïdie définitive</span></li></ul><p><strong>Selon l'étiologie</strong></p><ul><li><span class=\"kw-etio\">Nodule(s) hypersécrétant(s)</span> : pas de rémission spontanée → traitement radical nécessaire (<span class=\"kw-ttt\">chirurgie</span> ou <span class=\"kw-ttt\">radio-iode</span>)</li><li><span class=\"kw-etio\">Thyroïdite de De Quervain</span> : symptomatique (<span class=\"kw-ttt\">antalgiques</span>, <span class=\"kw-ttt\">antipyrétiques</span>, <span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">corticoïdes</span> si formes importantes)</li><li><span class=\"kw-etio\">Surcharge iodée</span> : <span class=\"kw-ttt\">ATS</span> si type 1 (fonctionnelle), <span class=\"kw-ttt\">corticoïdes</span> si type 2 (lésionnelle)</li><li><span class=\"kw-etio\">Thyrotoxicose gestationnelle</span> : symptomatique (repos, hydratation, ± <span class=\"kw-ttt\">β-bloquants</span>), régression spontanée</li></ul>","suivi":"<p><strong>Efficacité ATS :</strong> dosage de <span class=\"kw-bio\">T4 libre</span> à la <span class=\"kw-chiffre\">3e-4e semaine</span> (la <span class=\"kw-bio\">TSH</span> reste basse longtemps par inertie thyréotrope), puis <span class=\"kw-bio\">TSH</span> tous les <span class=\"kw-chiffre\">3 mois</span>.<br><strong>Tolérance ATS :</strong> <span class=\"kw-bio\">NFS</span> tous les <span class=\"kw-chiffre\">10 jours</span> pendant les <span class=\"kw-chiffre\">2 premiers mois</span> ; arrêt si <span class=\"kw-bio\">PNN</span> <span class=\"kw-chiffre\">< 1 G/L</span>, arrêt définitif + milieu protégé si <span class=\"kw-chiffre\">< 0,5 G/L</span>.<br><strong>Contrôle <span class=\"kw-bio\">TSH</span> :</strong> à au moins <span class=\"kw-chiffre\">6 semaines</span> d'intervalle.<br><strong>Basedow :</strong> surveillance prolongée car <span class=\"kw-etio\">récidives</span> et <span class=\"kw-etio\">hypothyroïdie</span> peuvent survenir des années après l'épisode initial.</p>"},"liensGlobaux":[{"href":"https://www.sfendocrino.org/item-242-hyperthyroidie/","label":"SFE — Item 242 hyperthyroidie"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Thyrotoxicose confirmée — TSH effondrée + T4L/T3L élevées","detail":"<h4>CAT — Orientation étiologique d'une thyrotoxicose — Évaluer la gravité, puis orienter selon morphologie thyroïdienne, TRAK et <span class=\"kw-imagerie\">scintigraphie</span></h4>","branches":[{"to":"q-gravite","label":"Évaluer la gravité","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes de gravité présents ? — Crise aiguë thyrotoxique, orbitopathie maligne, cardiothyréose","branches":[{"to":"t-urgence","label":"Oui — signe de gravité","color":"red"},{"to":"q-morpho","label":"Non","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence → hospitalisation immédiate","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">Crise aiguë thyrotoxique</span> → <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">unité de soins intensifs</span></li><li><span class=\"kw-etio\">Orbitopathie maligne</span> → avis <span class=\"kw-ttt\">ophtalmologique</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">< 48h</span>) + bolus de <span class=\"kw-ttt\">méthylprednisolone</span> ± <span class=\"kw-ttt\">décompression orbitaire</span></li><li><span class=\"kw-etio\">Cardiothyréose</span> → hospitalisation, <span class=\"kw-ttt\">β-bloquants</span> ; pas de traitement du trouble du rythme tant que l'hyperthyroïdie persiste</li></ul>"},{"id":"q-morpho","kind":"decision","label":"Aspect thyroïdien (palpation / échographie) ?","branches":[{"to":"t-nodule","label":"Goitre ou nodule(s)","color":"amber"},{"to":"q-trak","label":"Goitre diffus / thyroïde normale","color":"blue"}]},{"id":"t-nodule","kind":"terminal","label":"Nodule(s) hypersécrétant(s)","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Scintigraphie</span> : <span class=\"kw-radio\">nodule(s) extinctif(s) hyperfixant(s)</span>, tissu sain freiné (aspect en « <span class=\"kw-radio\">damier</span> » si goitre multinodulaire)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-etio\">Adénome toxique</span> ou <span class=\"kw-etio\">goitre multinodulaire toxique</span> : pas de rémission spontanée</li><li>Traitement radical après préparation par <span class=\"kw-ttt\">ATS</span> : <span class=\"kw-ttt\">chirurgie</span> ou <span class=\"kw-ttt\">radio-iode 131</span></li></ul>"},{"id":"q-trak","kind":"decision","label":"AC anti-récepteurs de la TSH (TRAK) ?","branches":[{"to":"t-basedow","label":"Positifs","color":"amber"},{"to":"t-thyroidite","label":"Négatifs (scintigraphie blanche)","color":"green"}]},{"id":"t-basedow","kind":"terminal","label":"Maladie de Basedow","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">TRAK</span> positifs ; <span class=\"kw-imagerie\">scintigraphie</span> : <span class=\"kw-radio\">hyperfixation diffuse et homogène</span></li><li><span class=\"kw-clinique\">Orbitopathie</span> spécifique = diagnostic assuré sans autre examen</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">ATS</span> en 1re intention (<span class=\"kw-chiffre\">12 à 18 mois</span>)</li><li>Traitement radical (<span class=\"kw-ttt\">radio-iode</span> ou <span class=\"kw-ttt\">thyroïdectomie</span>) si rechute, échec ou <span class=\"kw-etio\">cardiothyréose</span></li></ul>"},{"id":"t-thyroidite","kind":"terminal","label":"Scintigraphie blanche → thyroïdite / factice","color":"green","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">TRAK</span> négatifs, <span class=\"kw-imagerie\">scintigraphie</span> <span class=\"kw-radio\">blanche</span></li><li><span class=\"kw-bio\">Thyroglobuline</span> effondrée → <span class=\"kw-etio\">thyrotoxicose factice</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-etio\">Thyroïdite</span> (post-partum, silencieuse, de De Quervain) : traitement symptomatique, <span class=\"kw-clinique\">évolution</span> le plus souvent résolutive</li><li><span class=\"kw-etio\">De Quervain</span> : <span class=\"kw-ttt\">antalgiques</span>/<span class=\"kw-ttt\">AINS</span>, ± <span class=\"kw-ttt\">corticoïdes</span></li></ul>"}]},"cards":[{"i":"12ab4c2320b6","n":242,"o":"242-1","u":"Définition","t":"Connaître la définition de l’hyperthyroïdie et de la thyrotoxicose","q":"Quelle est la définition stricte de l'hyperthyroïdie ?","a":"<p>L'hyperthyroïdie correspond à l'ensemble des troubles liés à l'<strong>hyperfonctionnement de la glande thyroïde</strong>, qui sécrète elle-même un excès d'hormones thyroïdiennes.</p>"},{"i":"c95e9a136efd","n":242,"o":"242-1","u":"Définition","t":"Connaître la définition de l’hyperthyroïdie et de la thyrotoxicose","q":"Comment différencier l'hyperthyroïdie de la thyrotoxicose en cas de doutes diagnostiques ?","a":"<p>La scintigraphie thyroïdienne permet de trancher :</p><ul><li>Une glande qui <strong>hyperfonctionne</strong> (hyperthyroïdie) aura une scintigraphie <strong>fixante</strong>.</li><li>Une glande qui <strong>ne fonctionne pas</strong> (thyrotoxicose sans hyperthyroïdie, comme la thyrotoxicose factice ou certaines thyroïdites) aura une scintigraphie <strong>blanche</strong> ou non fixante.</li></ul>"},{"i":"dfad4fcc9965","n":242,"o":"242-1","u":"Définition","t":"Connaître la définition de l’hyperthyroïdie et de la thyrotoxicose","q":"Quelle est la définition stricte de la thyrotoxicose ?","a":"<p>La thyrotoxicose est l'ensemble des <strong>conséquences tissulaires</strong> de l'excès d'hormones thyroïdiennes au niveau des organes cibles, <strong>quelle qu'en soit la cause</strong>.</p>"},{"i":"4347861659b9","n":242,"o":"242-10","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’une maladie de Basedow","q":"Comment diagnostique-t-on la maladie de Basedow, notamment en présence ou absence de manifestations oculaires ?","a":"<ul><li>Devant des <strong>manifestations oculaires spécifiques</strong>, le diagnostic peut être assuré <strong>cliniquement</strong>.</li><li>Si les manifestations oculaires sont absentes, le diagnostic repose sur le dosage des <strong>TRAK en 1<sup>re</sup> intention</strong>. Un titre élevé confirme le diagnostic.</li><li>En <strong>2<sup>nde</sup> intention</strong>, si besoin, une <strong>scintigraphie thyroïdienne</strong> (montrant une hyperfixation diffuse et homogène) ou une <strong>échographie thyroïdienne</strong> (montrant une glande globalement hypoéchogène et très vascularisée, notamment en cas de grossesse) peut être réalisée.</li></ul>"},{"i":"8763d79a25b1","n":242,"o":"242-10","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’une maladie de Basedow","q":"Quel est le terrain épidémiologique typique de la maladie de Basedow ?","a":"<p>La maladie de Basedow touche majoritairement la <strong>femme jeune</strong>, entre 20 et 40 ans, avec un <strong>sex-ratio de 5 à 7 femmes pour 1 homme</strong>. Il existe souvent un <strong>terrain auto-immun personnel ou familial</strong> associé.</p>"},{"i":"911af299097c","n":242,"o":"242-10","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’une maladie de Basedow","q":"Quelle est la triade clinique caractéristique de la maladie de Basedow ?","a":"<ul><li>Un <strong>syndrome de thyrotoxicose</strong>.</li><li>Une <strong>orbitopathie dysthyroïdienne</strong>, présente chez 25 à 50% des patients.</li><li>Un <strong>goitre diffus, homogène, élastique et vasculaire</strong> (avec parfois un souffle systolique à l'auscultation de la thyroïde).</li></ul>"},{"i":"a733ebe8f2a9","n":242,"o":"242-10","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’une maladie de Basedow","q":"Quelle est la cause physiopathologique de la maladie de Basedow ?","a":"<p>La maladie de Basedow est une maladie <strong>auto-immune</strong> due à des <strong>anticorps anti-récepteurs de la TSH (TRAK)</strong> stimulants, qui activent la production hormonale thyroïdienne et agissent également sur les muscles oculomoteurs et la graisse orbitaire.</p>"},{"i":"2302a5125b9c","n":242,"o":"242-11","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’un nodule hypersécrétant","q":"Quels sont les critères diagnostiques cliniques et échographiques d'un adénome toxique de la thyroïde ?","a":"<p>Cliniquement, un adénome toxique se manifeste par un <strong>nodule thyroïdien unique</strong> palpable et un <strong>syndrome de thyrotoxicose pure</strong> (sans atteinte oculaire). À l'échographie, il apparaît comme un <strong>nodule tissulaire</strong> ou <strong>partiellement kystique</strong>.</p>"},{"i":"3e918697cdc1","n":242,"o":"242-11","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’un nodule hypersécrétant","q":"Quelle est la conduite à tenir devant un nodule thyroïdien associé à une TSH basse, notamment vis-à-vis de la cytoponction ?","a":"<p>Devant un nodule thyroïdien avec une <strong>TSH basse</strong>, il ne faut <strong>pas réaliser de cytoponction</strong>, même si le nodule est volumineux, irrégulier ou hypoéchogène. Une TSH basse signe son <strong>caractère fonctionnel et bénin</strong>.</p>"},{"i":"b0a08292733a","n":242,"o":"242-11","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’un nodule hypersécrétant","q":"Quel est l'aspect scintigraphique caractéristique d'un adénome toxique de la thyroïde, et quelle est son utilité diagnostique ?","a":"<p>La scintigraphie thyroïdienne révèle un <strong>nodule extinctif</strong>, c'est-à-dire que le nodule est le seul à fixer le traceur (fixation « chaude »), tandis que le <strong>tissu thyroïdien sain périphérique est freiné</strong> (fixation « froide »). Cet examen est <strong>nécessaire au diagnostic</strong>.</p>"},{"i":"cc40a711184c","n":242,"o":"242-11","u":"Diagnostic positif","t":"Connaître les critères diagnostiques d’un nodule hypersécrétant","q":"Quels sont les critères diagnostiques d'un goitre multinodulaire toxique, et quelle est sa population à risque ?","a":"<p>Le goitre multinodulaire toxique se caractérise cliniquement par un <strong>goitre multinodulaire</strong> et un <strong>syndrome de thyrotoxicose pure</strong>. La scintigraphie montre une alternance de plages fixantes et hypofixantes en « <strong>damier</strong> ». C'est la <strong>première cause d'hyperthyroïdie chez le sujet âgé</strong>.</p>"},{"i":"5d548b089284","n":242,"o":"242-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hyperthyroïdie","q":"Comment l'hyperthyroïdie affecte-t-elle le poids et la masse musculaire d'un patient ?","a":"<p>L'hyperthyroïdie entraîne un <strong>amaigrissement rapide et souvent important</strong>, contrastant avec un <strong>appétit conservé ou augmenté (polyphagie)</strong>. On peut observer une <strong>amyotrophie des racines</strong> avec baisse de force, comme le <strong>signe du tabouret</strong>.</p>"},{"i":"b2f4565849c0","n":242,"o":"242-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hyperthyroïdie","q":"Quels sont les principaux signes cardiovasculaires d'une hyperthyroïdie ?","a":"<ul><li><strong>Tachycardie régulière, sinusale</strong>, persistant au repos (signe le plus fréquent à <strong>96 %</strong> des cas).</li><li>Palpitations (<strong>86 %</strong>).</li><li>Dyspnée d'effort (<strong>73 %</strong>).</li><li>Éréthisme cardiaque.</li><li>Pouls vibrant.</li><li>Élévation de la Pression Artérielle Systolique (PAS).</li><li>Parfois, <strong>fibrillation auriculaire</strong> (<strong>10 %</strong>).</li></ul>"},{"i":"d5e2248cc9ea","n":242,"o":"242-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hyperthyroïdie","q":"Quels sont les signes neuropsychiques et de thermorégulation typiques rencontrés lors d'une hyperthyroïdie ?","a":"<ul><li><strong>Neuropsychiques</strong>: Tremblement fin et régulier des extrémités (<strong>73 %</strong>), nervosité (<strong>93 %</strong>), agitation psychomotrice, labilité de l'humeur, troubles du sommeil.</li><li><strong>Thermorégulation</strong>: Thermophobie (<strong>82 %</strong>), hypersudation (mains chaudes et moites à <strong>80 %</strong>), polydipsie (<strong>48 %</strong>).</li></ul>"},{"i":"f9b461f14e85","n":242,"o":"242-3","u":"Diagnostic positif","t":"Connaître les signes cliniques d’une hyperthyroïdie","q":"Quels pièges diagnostiques doivent être évités concernant l'hyperthyroïdie ?","a":"<p>Il convient d'être vigilant car l'<strong>Hypertension Artérielle (HTA)</strong>, l'<strong>asthénie</strong> et la <strong>dysménorrhée</strong> sont des manifestations <strong>communes avec l'hypothyroïdie</strong> et ne sont donc pas discriminantes à elles seules pour le diagnostic d'hyperthyroïdie.</p>"},{"i":"755b767d6c28","n":242,"o":"242-4","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une crise aiguë thyrotoxique","q":"Quelle est l'orientation immédiate face à une suspicion de crise aiguë thyrotoxique ?","a":"<p>L'orientation immédiate est une <strong>hospitalisation en unité de soins intensifs</strong>, compte tenu du caractère d'urgence vitale de cette pathologie.</p>"},{"i":"7618557d51a3","n":242,"o":"242-4","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une crise aiguë thyrotoxique","q":"Dans quel contexte clinique la crise aiguë thyrotoxique survient-elle le plus souvent ?","a":"<p>La crise aiguë thyrotoxique survient surtout après une <strong>thyroïdectomie</strong> en l'absence de préparation médicale par des <strong>antithyroïdiens de synthèse</strong>.</p>"},{"i":"bd3d022b414a","n":242,"o":"242-4","u":"Identifier une urgence","t":"Connaître les signes cliniques évocateurs d’une crise aiguë thyrotoxique","q":"Quels sont les signes cliniques évocateurs d'une crise aiguë thyrotoxique ?","a":"<ul><li>Une exacerbation majeure du <strong>syndrome de thyrotoxicose</strong></li><li>Une <strong>fièvre</strong> élevée</li><li>Une <strong>déshydratation</strong></li><li>Des <strong>troubles cardiovasculaires</strong> (tachycardie, arythmie, insuffisance cardiaque)</li><li>Des <strong>troubles neuropsychiques</strong> (agitation, confusion, coma)</li></ul>"},{"i":"00c8ace9daf7","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Quel est le piège à éviter lors du suivi initial d'un traitement par antithyroïdiens de synthèse (ATS) ?","a":"<p>Le piège est que la <strong>TSH peut rester basse longtemps</strong> sous traitement par ATS en raison de l'inertie thyréotrope. Par conséquent, l'efficacité initiale du traitement doit être évaluée sur la <strong>T4 libre</strong> (3ème-4ème semaine), et <strong>non sur la TSH</strong>.</p>"},{"i":"0758b24bd5be","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Quel est le délai minimal à respecter entre deux dosages de TSH et des dosages sous Anti-Thyroïdiens de Synthèse (ATS) ?","a":"<ul><li>Un contrôle de la TSH doit être réalisé au minimum à <strong>6 semaines d'intervalle</strong>.</li><li>Sous traitement par antithyroïdiens de synthèse (ATS), les dosages sont espacés d'au moins <strong>8 semaines</strong>.</li></ul>"},{"i":"32413a050301","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Quelles étiologies faut-il évoquer en présence d'une 'TSH inadaptée' (TSH normale ou élevée avec T4 libre élevée) ?","a":"<p>En présence d'une TSH normale ou élevée malgré une T4 libre élevée (TSH inadaptée), il faut évoquer une hyperthyroïdie <strong>d'origine centrale</strong>, telle qu'un <strong>adénome thyréotrope</strong> ou un <strong>syndrome de résistance aux hormones thyroïdiennes</strong>.</p>"},{"i":"3b4997f3d50f","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Dans quel cas unique est-il pertinent de doser la T3 libre pour le diagnostic d'hyperthyroïdie ?","a":"<p>La <strong>T3 libre</strong> n'a d'intérêt qu'en <strong>troisième intention</strong>, si la T4 libre est normale malgré une TSH basse, afin de dépister une <strong>hyperthyroïdie à T3 isolée</strong>.</p>"},{"i":"91a1eed024b0","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Comment interprète-t-on le dosage de la TSH dans le diagnostic d'une hyperthyroïdie périphérique ?","a":"<p>Dans le cas d'une hyperthyroïdie périphérique, la TSH est <strong>constamment effondrée</strong>. Si la TSH est basse, on dosera la T4 libre en deuxième intention.</p>"},{"i":"b634e806a2df","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Quelle est la stratégie de première intention pour le diagnostic biologique de l'hyperthyroïdie, conformément aux recommandations?","a":"<p>La stratégie de première intention consiste à doser la <strong>TSH (Thyroid Stimulating Hormone)</strong> seule. Cette approche est alignée sur les recommandations de la HAS et la modification UNCAM de mai 2024.</p>"},{"i":"cc1bc61194fb","n":242,"o":"242-6","u":"Diagnostic positif","t":"Connaître l’interprétation des dosages hormonaux","q":"Quand et pourquoi dose-t-on la T4 libre dans le bilan d'une hyperthyroïdie ?","a":"<p>La <strong>T4 libre</strong> est dosée en <strong>deuxième intention</strong>, uniquement si la TSH est basse. Elle permet d'apprécier l'importance de la thyrotoxicose.</p>"},{"i":"b6530a183a77","n":242,"o":"242-9","u":"Etiologies","t":"Connaître les trois étiologies les plus fréquentes d’hyperthyroïdie","q":"Qu'est-ce qu'un adénome toxique et quels sont ses caractères principaux dans le cadre d'une hyperthyroïdie ?","a":"<p>Un adénome toxique est caractérisé par un <strong>nodule unique</strong> hypersécrétant et <strong>autonome</strong>, produisant des hormones thyroïdiennes indépendamment de la régulation par la TSH.</p>"},{"i":"d688487fbee8","n":242,"o":"242-9","u":"Etiologies","t":"Connaître les trois étiologies les plus fréquentes d’hyperthyroïdie","q":"Quelle est la cause la plus fréquente d'hyperthyroïdie chez le sujet âgé ?","a":"<p>La cause la plus fréquente d'hyperthyroïdie chez le sujet âgé est le <strong>goitre multinodulaire toxique</strong>.</p>"},{"i":"eb4336507151","n":242,"o":"242-9","u":"Etiologies","t":"Connaître les trois étiologies les plus fréquentes d’hyperthyroïdie","q":"Quelle est la cause la plus fréquente d'hyperthyroïdie chez la femme jeune ?","a":"<p>La cause la plus fréquente d'hyperthyroïdie chez la femme jeune est la <strong>maladie de Basedow</strong>.</p>"}]};